mapper.update:
UPDATE user u JOIN user_privacy p ON u.user_num = p.user_num
SET u.user_name = #{userName}, u.user_email = #{userEmail},
p.up_gender = #{userGender}, p.up_height = #{userHeight}, p.up_weight = #{userWeight}, p.up_target_weight = #{userTargetweight}, p.up_age = #{userAge}, p.up_act = #{userAct}, p.up_model = #{userModel},
p.up_daily_kcal = #{userDailyKcal}, p.up_daily_carbs = #{userDailyCarbs}, p.up_daily_protein = #{userDailyProtein}, p.up_daily_fat = #{userDailyFat}, p.up_daily_natrium = #{userDailyNatrium}
WHERE u.user_num = #{userNum}

mapper.select:
SELECT user_password
FROM user
WHERE user_num = #{userNum}

SELECT user_num 
FROM user_social_accounts
WHERE usa_provider = '카톡' AND usa_provider_user_id = #{kakaoId}

SELECT mk.mk_num AS mkNum, md.mday_num AS mdayNum, IFNULL(SUM(md.md_kcal), 0) AS kcal, IFNULL(ROUND(SUM(f.fo_carbs * md.md_portion), 1), 0) AS carbs, IFNULL(ROUND(SUM(f.fo_protein * md.md_portion), 1), 0) AS protein, IFNULL(ROUND(SUM(f.fo_fat * md.md_portion), 1), 0) AS fat, IFNULL(ROUND(SUM(f.fo_natrium * md.md_portion), 1), 0) AS sodium FROM meal_detail md JOIN food f ON md.fo_num = f.fo_num JOIN meal_log mk ON md.mk_num = mk.mk_num
WHERE mk.user_num = #{userNum} AND DATE(mk.mk_created_at) = CURDATE() AND mk.mk_meal_type = #{mealType}
GROUP BY mk.mk_num, md.mday_num
